-- Distribute untouched initial approvals by business responsibility.
UPDATE approval_requests SET applicant_id='EMP-006',department_id='DEP-003',reviewer_id='EMP-004' WHERE id='APPR-900001' AND business_version=1 AND status='submitted';
UPDATE approval_requests SET applicant_id='EMP-008',department_id='DEP-003',reviewer_id='EMP-004' WHERE id='APPR-900002' AND business_version=1 AND status='submitted';
UPDATE approval_requests SET reviewer_id='EMP-005' WHERE id='APPR-900004' AND business_version=1 AND status='submitted';
UPDATE business_tasks SET assignee_id=(SELECT reviewer_id FROM approval_requests a WHERE a.session_id=business_tasks.session_id AND a.id=business_tasks.source_id) WHERE status='open' AND source_type='approval' AND source_id IN ('APPR-900001','APPR-900002','APPR-900004') AND EXISTS(SELECT 1 FROM approval_requests a WHERE a.session_id=business_tasks.session_id AND a.id=business_tasks.source_id AND a.business_version=1 AND a.status='submitted');
SELECT session_id,'TODO-910000','补正：'||title,applicant_id,'approval',id,created_at,'open' FROM approval_requests a WHERE id='APPR-002' AND status='returned' AND NOT EXISTS(SELECT 1 FROM business_tasks t WHERE t.session_id=a.session_id AND t.source_type='approval' AND t.source_id=a.id AND t.status='open');
UPDATE demo_sessions SET dataset_version='2026-10-16.1';
